#!/bin/bash
# Task 106-w25-v1261-accept-evm-zone-29 -- meshsim acceptance kit (WORKER11; v1.26: WORKER20; v1.26.1: WORKER25, branch v1.26.1). The kit (meshsim.jar, Java 17 bytecode;
# the prebuilt replay controller; the universal replayer tables; run_shard.sh, calibrate.sh) is embedded below as a base64
# tgz, SHA-256 checked. Runs: ./run_shard.sh -d "$W/v1261" -p evm-zone-29 -M "$W/v1261/evm-zone-29.manifest.json" -f 0 -n 8192 -j 16 -x 64 "$RES/evm-zone-29"
# Commits only results (CSV, summaries, logs); deliveries are generated into scratch and deleted (DECISIONS-v1.25 s7).
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/106-w25-v1261-accept-evm-zone-29; mkdir -p "$RES"
WANT=8aa265ce9772719678de08e0cef116caf05bc4838c0240bbffc7fa3dc0475ab2
W=/tmp/w11-106-w25-v1261-accept-evm-zone-29; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
cd "$W/w11-kit" || exit 2
sha256sum -c --quiet HASHES || { echo "kit files differ from HASHES"; exit 2; }
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1; free -g | head -2
REPO=${RES%/results/*}
# Persistent runner data (Quest PIPELINE.md, "Persistent data on the runner"): ~questrunner/data (owner), writable once the
# unit's ReadWritePaths lists it; else the git-ignored data/ in the queue checkout. Never /tmp (wiped at boot).
DATA=$HOME/data
{ mkdir -p "$DATA" && touch "$DATA/.writable" && rm -f "$DATA/.writable"; } 2>/dev/null || DATA=$REPO/data
mkdir -p "$DATA" || { echo "no writable persistent data directory ($HOME/data, $REPO/data)"; exit 4; }
# v1.26.1 (WORKER25): WORKER9's v1.25 deliveries, regenerated into persistent data by tasks 103/104 (079/080's writer and
# inputs), converted into scratch by ConvertDelivery: the state records rewritten to v1.26.1's 68 words (DECISIONS-v1.26 items 1, 2,
# 15, 16: no flags in the state word, the new stream word), every other file a link (the delivery is only read). Scratch is rm -rf'ed at the start: safe to re-run after a reboot.
SRC=$DATA/w9-deliveries
echo "deliveries: $SRC"
for PS in evm-zone-29:7142e894c80a0c9d491f21c852a942885e0abd97cfe6aefd0101d716824e138f; do
  P=${PS%%:*}; SM=${PS#*:}
  [ -f "$SRC/$P.COMPLETE" ] || { echo "$SRC/$P.COMPLETE missing: run tasks 103/104 (the deliveries) first"; rm -rf "$W"; exit 2; }
  GOT=$(sha256sum "$SRC/$P.manifest.json" 2>/dev/null | cut -d' ' -f1)
  [ "$GOT" = "$SM" ] && [ "$GOT" = "$(cat "$SRC/$P.COMPLETE")" ] || { echo "$SRC/$P.manifest.json sha256 '$GOT', expected $SM"; rm -rf "$W"; exit 2; }
  java -Xmx2g -cp meshsim.jar ConvertDelivery "$SRC" "$W/v1261" "$P" > "$RES/convert-$P.log" 2>&1; CRC=$?
  cat "$RES/convert-$P.log"; [ $CRC = 0 ] || { echo "conversion of $P failed"; rm -rf "$W"; exit 1; }
done
./run_shard.sh -d "$W/v1261" -p evm-zone-29 -M "$W/v1261/evm-zone-29.manifest.json" -f 0 -n 8192 -j 16 -x 64 "$RES/evm-zone-29"; RC=$?
echo "exit $RC at $(date -u)"
rm -rf "$W"
exit $RC
